-- Model: lnk_placement_billingprofile__placement_hkey_curr
-- Description: Current active relationship for LNK_PLACEMENT_BILLINGPROFILE using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_PLACEMENT_BILLINGPROFILE_HKEY AS LNK_PLACEMENT_BILLINGPROFILE_HKEY,
    l.PLACEMENT_HKEY AS PLACEMENT_HKEY,
    l.BILLINGPROFILE_HKEY AS BILLINGPROFILE_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.DATELASTSYNC

    ROW_NUMBER() OVER (
        PARTITION BY l.PLACEMENT_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.DATELASTSYNC
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_placement_billingprofile') }} l
INNER JOIN {{ ref('lks_bh1_placement_billingprofile_curr') }} ls
    ON l.LNK_PLACEMENT_BILLINGPROFILE_HKEY = ls.LNK_PLACEMENT_BILLINGPROFILE_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
